default.shell:
$mismatchCount = 0

$key = Get-Item -LiteralPath 'HKLM:\Software\Microsoft\Windows\CurrentVersion\Policies\System\kerberos\parameters' -ErrorAction SilentlyContinue
$current = $null
if ($key) { $current = $key.GetValue('DevicePKInitBehavior', $null, 'DoNotExpandEnvironmentNames') }
if (-not ($current -is [int] -and [BitConverter]::ToUInt32([BitConverter]::GetBytes($current), 0) -eq [uint32]0)) {
    Write-Output 'Mismatch: HKLM:\Software\Microsoft\Windows\CurrentVersion\Policies\System\kerberos\parameters [DevicePKInitBehavior]'
    $mismatchCount++
}

$key = Get-Item -LiteralPath 'HKLM:\Software\Microsoft\Windows\CurrentVersion\Policies\System\kerberos\parameters' -ErrorAction SilentlyContinue
$current = $null
if ($key) { $current = $key.GetValue('DevicePKInitEnabled', $null, 'DoNotExpandEnvironmentNames') }
if (-not ($current -is [int] -and [BitConverter]::ToUInt32([BitConverter]::GetBytes($current), 0) -eq [uint32]1)) {
    Write-Output 'Mismatch: HKLM:\Software\Microsoft\Windows\CurrentVersion\Policies\System\kerberos\parameters [DevicePKInitEnabled]'
    $mismatchCount++
}

if ($mismatchCount -gt 0) { exit 1 }
exit 0

steps.shell:
$ErrorActionPreference = 'Stop'
trap { Write-Output $_.Exception.Message; exit 1 }

if (-not (Test-Path -LiteralPath 'HKLM:\Software\Microsoft\Windows\CurrentVersion\Policies\System\kerberos\parameters')) {
    New-Item -Path 'HKLM:\Software\Microsoft\Windows\CurrentVersion\Policies\System\kerberos\parameters' -Force | Out-Null
}
New-ItemProperty -LiteralPath 'HKLM:\Software\Microsoft\Windows\CurrentVersion\Policies\System\kerberos\parameters' -Name 'DevicePKInitBehavior' -Value 0 -PropertyType DWord -Force | Out-Null
if (-not (Test-Path -LiteralPath 'HKLM:\Software\Microsoft\Windows\CurrentVersion\Policies\System\kerberos\parameters')) {
    New-Item -Path 'HKLM:\Software\Microsoft\Windows\CurrentVersion\Policies\System\kerberos\parameters' -Force | Out-Null
}
New-ItemProperty -LiteralPath 'HKLM:\Software\Microsoft\Windows\CurrentVersion\Policies\System\kerberos\parameters' -Name 'DevicePKInitEnabled' -Value 1 -PropertyType DWord -Force | Out-Null
exit 0
